package com.autohost.api.web;

import com.autohost.api.config.AppProperties;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import org.springframework.core.io.*;
import org.springframework.http.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import java.nio.file.*;
import java.util.*;

@RestController @RequestMapping("/api/vehicles")
public class VehicleController {
    @PersistenceContext EntityManager em;
    private final AppProperties props; private final ObjectMapper json;
    private static final long MAX_FILE=15L*1024*1024;
    private static final Set<String> TYPES=Set.of("image/jpeg","image/png","image/webp");
    public VehicleController(AppProperties props,ObjectMapper json){this.props=props;this.json=json;}
    @GetMapping @Transactional(readOnly=true) public Map<String,Object> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int pageSize,@RequestParam(defaultValue="false")boolean includeInactive){
        int size=Math.min(10,Math.max(1,pageSize)),p=Math.max(1,page),offset=(p-1)*size;String where=includeInactive?"":"WHERE v.IsActive=1 ";
        Number total=(Number)em.createNativeQuery("SELECT COUNT(*) FROM Vehiculos v "+where).getSingleResult();
        List<?> rows=em.createNativeQuery("SELECT v.id,v.VIN,v.Placa,v.Marca,v.Modelo,v.Anio,v.Version,v.Color,v.Fotos,v.Estatus,v.IsActive,v.MecanicoId,v.ClienteId,v.CreatedAt,v.UpdatedAt,u.DisplayName,CONCAT_WS(' ',c.Nombre,c.ApellidoPaterno,c.ApellidoMaterno) FROM Vehiculos v LEFT JOIN Users u ON u.UserId=v.MecanicoId LEFT JOIN Clients c ON c.ClientId=v.ClienteId "+where+"ORDER BY v.CreatedAt DESC,v.id LIMIT :size OFFSET :offset").setParameter("size",size).setParameter("offset",offset).getResultList();
        String[] names={"id","VIN","Placa","Marca","Modelo","Anio","Version","Color","Fotos","Estatus","IsActive","MecanicoId","ClienteId","CreatedAt","UpdatedAt","MecanicoNombre","ClienteNombre"};
        return page(rows,names,total,p,size,includeInactive);
    }
    private Map<String,Object> page(List<?> rows,String[] names,Number total,int p,int size,boolean inactive){List<Map<String,Object>>items=maps(rows,names);long count=total.longValue();Map<String,Object> out=new LinkedHashMap<>();out.put("items",items);out.put("total",count);out.put("page",p);out.put("pageSize",size);out.put("totalPages",(count+size-1)/size);out.put("includeInactive",inactive);return out;}
    @GetMapping("/mechanics") @Transactional(readOnly=true) public List<Map<String,Object>> mechanics(){List<?>rows=em.createNativeQuery("SELECT DISTINCT u.UserId,u.DisplayName FROM Users u JOIN UserAdministration a ON a.UserId=u.UserId JOIN Roles r ON r.RoleId=a.RoleId WHERE u.IsActive=1 AND r.IsActive=1 AND LOWER(r.RoleName) IN ('mecánico','mecanico') ORDER BY u.DisplayName").getResultList();return maps(rows,new String[]{"UserId","DisplayName"});}
    @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional public ResponseEntity<?> create(@RequestParam Map<String,String> body,@RequestPart(value="fotos",required=false)List<MultipartFile>photos){Map<String,String> v=normalize(body);validate(v,false);List<String> paths=store(photos);String id=UUID.randomUUID().toString();
        em.createNativeQuery("INSERT INTO Vehiculos(id,VIN,Placa,Marca,Modelo,Anio,Version,Color,Fotos,Estatus,IsActive,MecanicoId) VALUES(:id,:vin,:plate,:brand,:model,:year,:version,:color,:photos,:status,1,:mechanic)").setParameter("id",id).setParameter("vin",v.get("VIN")).setParameter("plate",v.get("Placa")).setParameter("brand",v.get("Marca")).setParameter("model",v.get("Modelo")).setParameter("year",Integer.valueOf(v.get("Anio"))).setParameter("version",v.get("Version")).setParameter("color",v.get("Color")).setParameter("photos",write(paths)).setParameter("status",v.get("Estatus")).setParameter("mechanic",blankNull(v.get("MecanicoId"))).executeUpdate();
        return ResponseEntity.status(201).body(Map.of("id",id,"message","Vehículo registrado correctamente."));}
    @PutMapping(value="/{id}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional public Map<String,String> update(@PathVariable String id,@RequestParam Map<String,String> body,@RequestPart(value="fotos",required=false)List<MultipartFile>files){Map<String,String>v=normalize(body);validate(v,true);List<?>existing=em.createNativeQuery("SELECT Fotos FROM Vehiculos WHERE id=:id AND IsActive=1").setParameter("id",id).getResultList();if(existing.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"No se encontró el vehículo activo.");List<String> photos=read(existing.get(0));photos.addAll(store(files));int active="desactivado".equals(v.get("Estatus"))?0:1;
        em.createNativeQuery("UPDATE Vehiculos SET VIN=:vin,Placa=:plate,Marca=:brand,Modelo=:model,Anio=:year,Version=:version,Color=:color,Fotos=:photos,Estatus=:status,IsActive=:active,MecanicoId=:mechanic WHERE id=:id AND IsActive=1").setParameter("vin",v.get("VIN")).setParameter("plate",v.get("Placa")).setParameter("brand",v.get("Marca")).setParameter("model",v.get("Modelo")).setParameter("year",Integer.valueOf(v.get("Anio"))).setParameter("version",v.get("Version")).setParameter("color",v.get("Color")).setParameter("photos",write(photos)).setParameter("status",v.get("Estatus")).setParameter("active",active).setParameter("mechanic",blankNull(v.get("MecanicoId"))).setParameter("id",id).executeUpdate();return Map.of("message",active==1?"Vehículo actualizado correctamente.":"Vehículo desactivado correctamente.");}
    @DeleteMapping("/{id}") @Transactional public Map<String,String> remove(@PathVariable String id){if(em.createNativeQuery("UPDATE Vehiculos SET IsActive=0,Estatus='desactivado' WHERE id=:id AND IsActive=1").setParameter("id",id).executeUpdate()==0)throw new ApiException(HttpStatus.NOT_FOUND,"No se encontró el vehículo activo.");return Map.of("message","Vehículo desactivado correctamente.");}
    @GetMapping("/photos/{filename}") public ResponseEntity<Resource> photo(@PathVariable String filename){if(!filename.matches("(?i)[0-9a-f-]{36}\\.(jpg|png|webp)"))throw new ApiException(HttpStatus.NOT_FOUND,"No se encontró la fotografía.");Path path=Paths.get(props.uploadRoot(),"vehicles",filename).normalize();if(!path.startsWith(Paths.get(props.uploadRoot()).resolve("vehicles").normalize())||!Files.isRegularFile(path))throw new ApiException(HttpStatus.NOT_FOUND,"No se encontró la fotografía.");String type=filename.endsWith(".png")?"image/png":filename.endsWith(".webp")?"image/webp":"image/jpeg";return ResponseEntity.ok().contentType(MediaType.parseMediaType(type)).body(new FileSystemResource(path));}
    private Map<String,String>normalize(Map<String,String>b){Map<String,String>v=new HashMap<>();for(String f:new String[]{"VIN","Placa","Marca","Modelo","Anio","Version","Color","Estatus","MecanicoId"})v.put(f,Objects.toString(b.get(f),"").trim());v.put("VIN",v.get("VIN").toLowerCase(Locale.ROOT));v.put("Placa",v.get("Placa").toLowerCase(Locale.ROOT).replaceAll("[\\s-]+",""));if(v.get("Estatus").isBlank())v.put("Estatus","activo");return v;}
    private void validate(Map<String,String>v,boolean editing){if(!v.get("VIN").matches("[a-hj-npr-z0-9]{17}"))throw new ApiException(HttpStatus.BAD_REQUEST,"El VIN debe tener 17 caracteres en minúsculas y excluir I, O y Q.");if(!v.get("Placa").matches("(?:[a-z]{3}[0-9]{4}|[a-z]{2}[0-9]{4}[a-z]|[a-z]{3}[0-9]{3}[a-z])"))throw new ApiException(HttpStatus.BAD_REQUEST,"La placa no coincide con un formato mexicano admitido.");for(String f:new String[]{"Marca","Modelo","Anio","Version","Color"})if(v.get(f).isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"El campo "+f+" es obligatorio.");try{int year=Integer.parseInt(v.get("Anio"));if(year<1886||year>java.time.Year.now().getValue()+1)throw new NumberFormatException();}catch(NumberFormatException e){throw new ApiException(HttpStatus.BAD_REQUEST,"Indica un año de modelo válido.");}if(!Set.of("activo","en_taller","desactivado").contains(v.get("Estatus")))throw new ApiException(HttpStatus.BAD_REQUEST,"Estatus inválido.");if(!editing&&"desactivado".equals(v.get("Estatus")))throw new ApiException(HttpStatus.BAD_REQUEST,"Un vehículo nuevo no puede registrarse como desactivado.");String mechanic=blankNull(v.get("MecanicoId"));if(mechanic!=null&&em.createNativeQuery("SELECT u.UserId FROM Users u JOIN UserAdministration a ON a.UserId=u.UserId JOIN Roles r ON r.RoleId=a.RoleId WHERE u.UserId=:id AND u.IsActive=1 AND r.IsActive=1 AND LOWER(r.RoleName) IN ('mecánico','mecanico') LIMIT 1").setParameter("id",mechanic).getResultList().isEmpty())throw new ApiException(HttpStatus.BAD_REQUEST,"El técnico debe ser un usuario activo con rol mecánico.");}
    private List<String>store(List<MultipartFile>files){if(files==null||files.isEmpty())return new ArrayList<>();if(files.size()>10)throw new ApiException(HttpStatus.BAD_REQUEST,"Se permiten hasta 10 fotografías por vehículo.");List<String>paths=new ArrayList<>();try{Path dir=Paths.get(props.uploadRoot(),"vehicles");Files.createDirectories(dir);for(MultipartFile f:files){if(f.isEmpty()||f.getSize()>MAX_FILE||!TYPES.contains(f.getContentType()))throw new ApiException(HttpStatus.BAD_REQUEST,"Cada fotografía debe ser JPG, PNG o WEBP y pesar como máximo 15 MB.");String ext=switch(f.getContentType()){case "image/png"->".png";case "image/webp"->".webp";default->".jpg";};String name=UUID.randomUUID()+ext;f.transferTo(dir.resolve(name));paths.add("/api/vehicles/photos/"+name);}return paths;}catch(ApiException e){throw e;}catch(Exception e){throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,"No se pudieron guardar las fotografías.");}}
    private String write(List<String>p){try{return json.writeValueAsString(p);}catch(Exception e){throw new IllegalStateException(e);}}
    private List<String>read(Object value){try{if(value instanceof String s)return json.readValue(s,new TypeReference<>(){});return json.convertValue(value,new TypeReference<>(){});}catch(Exception e){return new ArrayList<>();}}
    private static String blankNull(String s){return s==null||s.isBlank()?null:s;}
    private static List<Map<String,Object>>maps(List<?>rows,String[]names){return rows.stream().map(x->{Object[]r=(Object[])x;Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<names.length;i++)m.put(names[i],r[i]);return m;}).toList();}
}
